import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n_str = next(iterator)
            n = int(n_str)
        except StopIteration:
            break

        p = [-1] * n
        curr = n - 1

        while curr >= 0:
            s_sq = (curr + curr) // 2
            k = int(s_sq ** 0.5)
            if k * k < curr + curr:
                k += 1

            target = k * k
            start = target - curr

            if start < 0:
                results.append("-1")
                break

            if start > curr:
                results.append("-1")
                break

            count = curr - start + 1
            for i in range(count):
                p[curr - i] = start + i

            curr = start - 1

        if p[0] != -1:
            results.append(" ".join(map(str, p)))

    sys.stdout.write("\n".join(results) + "\n")

if __name__ == "__main__":
    solve()
